/*
 *  rest_worm()
 *
 *  Restore the worm information from the save file.  Called from restore.c
 */
/**
 * @param {$T.nh_file | null} nhfp NHFILE *
 * @returns {Promise<void>}
 */
export async function rest_worm(nhfp) {   // worm.c:577
    let i = 0, j = 0, count = Int32Array.of(0), curr = null, temp = null;
    count[0] = 0;
    for (i = 1; i < MAX_NUM_WORMS; i = i + 1 | 0) {
        await sfi_int(nhfp, new $c.Ptr(count, 0), $c.lit("worm-segment_count"));
        /* Get the segments. */
        for (curr = null, j = 0; j < count[0]; j = j + 1 | 0) {
            temp = await newseg();
            temp.nseg = null;
            await sfi_int16(nhfp, new $c.FieldRef(temp, "wx", "i16"), $c.lit("worm-wx"));
            await sfi_int16(nhfp, new $c.FieldRef(temp, "wy", "i16"), $c.lit("worm-wy"));
            if (curr) {
                curr.nseg = temp;
            } else {
                wtails[i] = temp;
            }
            curr = temp;
        }
        wheads[i] = curr;
    }
    for (i = 0; i < MAX_NUM_WORMS; i = i + 1 | 0) {
        await sfi_long(nhfp, new $c.Ptr(wgrowtime, i), $c.lit("worm-wgrowtime"));
    }
}
/*
 *  place_wsegs()
 *
 *  Place the segments of the given worm.  Called from restore.c
 *  and from replmon() in mon.c.
 *  If oldworm is not NULL, assumes the oldworm segments are on map
 *  in the same location as worm segments
 */
/**
 * @param {$T.monst | null} worm struct monst *
 * @param {$T.monst | null} oldworm struct monst *
 * @returns {Promise<void>}
 */
export async function place_wsegs(worm, oldworm) {   // worm.c:615
    let curr = null, x = 0, y = 0, mtmp = null;
    curr = wtails[worm.wormno];
    while (!$c.peq(curr, wheads[worm.wormno])) {
        x = curr.wx;
        y = curr.wy;
        mtmp = svl.level.monsters[x][y];
        if (oldworm && $c.peq(mtmp, oldworm)) {
            remove_monster(x, y);
        } else if (mtmp) {
            await impossible($c.lit("placing worm seg <%d,%d> over another mon"), x, y);
        } else if (oldworm) {
            await impossible($c.lit("replacing worm seg <%d,%d> on empty spot"), x, y);
        }
        svl.level.monsters[x][y] = worm;
        curr = curr.nseg;
    }
    /* head segment is co-located with worm itself so not placed on the map */
    curr.wx = worm.mx, curr.wy = worm.my;
}
/* called from mon_sanity_check(mon.c) */
/**
 * @param {$T.monst | null} worm struct monst *
 * @returns {Promise<void>}
 */
export async function sanity_check_worm(worm) {   // worm.c:639
    let curr = null, wnum = 0, x = 0, y = 0;
    if (!worm) {
        await impossible($c.lit("worm_sanity: null monster!"));
        return;
    }
    /* note: wormno can't be less than 0 (unsigned bit field) and can't
       be greater that MAX_NUM_WORMS - 1 (which uses all available bits)
       so checking for 0 is all we can manage for wormno validation;
       since caller has already done that, this is rather pointless... */
    if (!worm.wormno) {
        await impossible($c.lit("worm_sanity: not a worm!"));
        return;
    }
    wnum = worm.wormno | 0;
    if (!wtails[wnum] || !wheads[wnum]) {
        await impossible($c.lit("wormno %d is set without proper tail"), wnum);
        return;
    }
    /* if worm is migrating, we can't check its segments against the map */
    if (!worm.mx) {
        return;
    }
    curr = wtails[wnum];
    while (!$c.peq(curr, wheads[wnum])) {
        x = curr.wx, y = curr.wy;
        if (!isok($c.i16(x), $c.i16(y))) {
            await impossible($c.lit("worm seg not isok <%d,%d>"), x, y);
        } else if (!$c.peq(svl.level.monsters[x][y], worm)) {
            await impossible($c.lit("mon (%s) at seg location is not worm (%s)"), fmt_ptr(svl.level.monsters[x][y]), fmt_ptr(worm));
        }
        curr = curr.nseg;
    }
}
