/*
 *  remove_worm()
 *
 *  This function is equivalent to the remove_monster #define in
 *  rm.h, only it will take the worm *and* tail out of the levels array.
 *  It does not get rid of (dealloc) the worm tail structures, and it does
 *  not remove the mon from the fmon chain.
 */
/**
 * @param {$T.monst | null} worm struct monst *
 * @returns {Promise<void>}
 */
export async function remove_worm(worm) {   // worm.c:714
    let curr = null;
    curr = wtails[worm.wormno];
    while (curr) {
        if (curr.wx) {
            svl.level.monsters[curr.wx][curr.wy] = null;
            await newsym(curr.wx, curr.wy);
            curr.wx = 0;
        }
        curr = curr.nseg;
    }
}
/*
 *  place_worm_tail_randomly()
 *
 *  Place a worm tail somewhere on a level behind the head.
 *  This routine essentially reverses the order of the wsegs from head
 *  to tail while placing them.
 *  x, and y are most likely the worm->mx, and worm->my, but don't *need* to
 *  be, if somehow the head is disjoint from the tail.
 */
/**
 * @param {$T.monst | null} worm struct monst *
 * @param {number} x coordxy
 * @param {number} y coordxy
 * @returns {Promise<void>}
 */
export async function place_worm_tail_randomly(worm, x, y) {   // worm.c:738
    let wnum = 0, curr = null, new_tail = null, ox = 0, oy = 0, nx = Int16Array.of(0), ny = Int16Array.of(0), $t1, $t2, $t3, $t4;
    wnum = worm.wormno | 0;
    curr = wtails[wnum];
    ox = x;
    oy = y;
    if (wnum && (!wtails[wnum] || !wheads[wnum])) {
        await impossible($c.lit("place_worm_tail_randomly: wormno is set without a tail!"));
        return;
    }
    if ($c.peq(wtails[wnum], wheads[wnum])) {
        /* single segment, co-located with worm;
           should either have same coordinates or have seg->wx==0
           to indicate that it is not currently on the map */
        if (curr.wx && (curr.wx !== worm.mx || curr.wy !== worm.my)) {
            await impossible($c.lit("place_worm_tail_randomly: tail segment at <%d,%d>, worm at <%d,%d>"), curr.wx, curr.wy, worm.mx, worm.my);
            if ($c.peq(svl.level.monsters[curr.wx][curr.wy], worm)) {
                svl.level.monsters[curr.wx][curr.wy] = null;
            }
        }
        curr.wx = worm.mx, curr.wy = worm.my;
        return;
    }
    /* remove head segment from map in case we end up calling toss_wsegs();
       if it doesn't get tossed, it will become the final tail segment and
       get new coordinates */
    $t1 = wheads[wnum].wy = 0, wheads[wnum].wx = $t1;
    $t2 = new_tail = curr, wheads[wnum] = $t2;
    curr = curr.nseg;
    new_tail.nseg = null;
    new_tail.wx = x;
    new_tail.wy = y;
    while (curr) {
        nx[0] = $c.i16(ox);
        ny[0] = $c.i16(oy);
        if (await rnd_nextto_goodpos(new $c.Ptr(nx, 0), new $c.Ptr(ny, 0), worm)) {
            svl.level.monsters[nx[0]][ny[0]] = worm;
            $t3 = $c.i16(ox = nx[0]), curr.wx = $t3;
            $t4 = $c.i16(oy = ny[0]), curr.wy = $t4;
            wtails[wnum] = curr;
            curr = curr.nseg;
            wtails[wnum].nseg = new_tail;
            new_tail = wtails[wnum];
            await newsym(nx[0], ny[0]);
        } else {
            /* Oops.  Truncate because there is no place for rest of it. */
            await toss_wsegs(curr, FALSE);
            curr = null;
        }
    }
}
