/* for size_monst(cmd.c) to support #stats */
/**
 * @param {$T.monst | null} worm struct monst *
 * @returns {number} int
 */
export function size_wseg(worm) {   // worm.c:827
    return $c.i32($c.mulu64($c.u64(count_wsegs(worm)), 16));
}
/*  count_wsegs()
 *  returns the number of segments that a worm has.
 */
/**
 * @param {$T.monst | null} mtmp struct monst *
 * @returns {number} int
 */
export function count_wsegs(mtmp) {   // worm.c:836
    let i = 0, curr = null;
    i = 0;
    if (mtmp.wormno) {
        for (curr = wtails[mtmp.wormno].nseg; curr; curr = curr.nseg) {
            i = i + 1 | 0;
        }
    }
    return i;
}
/*  create_worm_tail()
 *  will create a worm tail chain of (num_segs + 1) and return pointer to it.
 */
/**
 * @param {number} num_segs int
 * @returns {Promise<$T.wseg | null>} struct wseg *
 */
async function create_worm_tail(num_segs) {   // worm.c:852
    let i = 0, new_tail = null, curr = null, $t1;
    i = 0;
    if (!num_segs) {
        return null;
    }
    new_tail = curr = await newseg();
    curr.nseg = null;
    curr.wx = 0;
    curr.wy = 0;
    while (i < num_segs) {
        $t1 = await newseg(), curr.nseg = $t1;
        curr = curr.nseg;
        curr.nseg = null;
        curr.wx = 0;
        curr.wy = 0;
        i = i + 1 | 0;
    }
    return new_tail;
}
/*  worm_known()
 *  Is any segment of this worm in viewing range?  Note: caller must check
 *  invisibility and telepathy (which should only show the head anyway).
 *  Mostly used in the canseemon() macro.
 */
/**
 * @param {$T.monst | null} worm struct monst *
 * @returns {number} boolean
 */
export function worm_known(worm) {   // worm.c:883
    let curr = null;
    curr = wtails[worm.wormno];
    while (curr) {
        if (cansee(curr.wx, curr.wy)) {
            return TRUE;
        }
        curr = curr.nseg;
    }
    return FALSE;
}
/* would moving from <x1,y1> to <x2,y2> involve passing between two
   consecutive segments of the same worm? */
/**
 * @param {number} x1 int
 * @param {number} y1 int
 * @param {number} x2 int
 * @param {number} y2 int
 * @returns {Promise<number>} boolean
 */
export async function worm_cross(x1, y1, x2, y2) {   // worm.c:898
    let worm = null, curr = null, wnxt = null;
    /*
     * With digits representing relative sequence number of the segments,
     * returns true when testing between @ and ? (passes through worm's
     * body), false between @ and ! (stays on same side of worm).
     *  .w1?..
     *  ..@2..
     *  .65!3.
     *  ...4..
     */
    if (distmin($c.i16(x1), $c.i16(y1), $c.i16(x2), $c.i16(y2)) !== 1) {
        await impossible($c.lit("worm_cross checking for non-adjacent location?"));
        return FALSE;
    }
    /* attempting to pass between worm segs is only relevant for diagonal */
    if (x1 === x2 || y1 === y2) {
        return FALSE;
    }
    /* is the same monster at <x1,y2> and at <x2,y1>? */
    worm = svl.level.monsters[x1][y2];
    if (!worm || !$c.peq(svl.level.monsters[x2][y1], worm)) {
        return FALSE;
    }
    /* same monster is at both adjacent spots, so must be a worm; we need
       to figure out if the two spots are occupied by consecutive segments */
    for (curr = wtails[worm.wormno]; curr; curr = wnxt) {
        wnxt = curr.nseg;
        if (!wnxt) {
            break;   /* no next segment; can't continue */
        }
        /* we don't know which of <x1,y2> or <x2,y1> we'll hit first, but
           whichever it is, they're consecutive iff next seg is the other */
        if (curr.wx === x1 && curr.wy === y2) {
            return $c.i8(wnxt.wx === x2 && wnxt.wy === y1 ? 1 : 0);
        }
        if (curr.wx === x2 && curr.wy === y1) {
            return $c.i8(wnxt.wx === x1 && wnxt.wy === y2 ? 1 : 0);
        }
    }
    /* should never reach here... */
    return FALSE;
}
/* construct an index number for a worm tail segment */
/**
 * @param {$T.monst | null} worm struct monst *
 * @param {number} x int
 * @param {number} y int
 * @returns {number} int
 */
export function wseg_at(worm, x, y) {   // worm.c:946
    let res = 0, curr = null, i = 0, n = 0, wx = 0, wy = 0;
    res = 0;
    if (worm && worm.wormno | 0 && $c.peq(svl.level.monsters[x][y], worm)) {
        wx = $c.i16(x);
        wy = $c.i16(y);
        for (i = 0, curr = wtails[worm.wormno]; curr; curr = curr.nseg) {
            if (curr.wx === wx && curr.wy === wy) {
                break;
            }
            i = i + 1 | 0;
        }
        for (n = i; curr; curr = curr.nseg) {
            n = n + 1 | 0;
        }
        res = n - i | 0;
    }
    return res;
}
/**
 * @param {$T.monst | null} worm struct monst *
 * @param {number} miny int
 * @param {number} maxy int
 */
export function flip_worm_segs_vertical(worm, miny, maxy) {   // worm.c:968
    let curr = null;
    curr = wtails[worm.wormno];
    while (curr) {
        curr.wy = $c.i16((maxy - curr.wy | 0) + miny | 0);
        curr = curr.nseg;
    }
}
/**
 * @param {$T.monst | null} worm struct monst *
 * @param {number} minx int
 * @param {number} maxx int
 */
export function flip_worm_segs_horizontal(worm, minx, maxx) {   // worm.c:979
    let curr = null;
    curr = wtails[worm.wormno];
    while (curr) {
        curr.wx = $c.i16((maxx - curr.wx | 0) + minx | 0);
        curr = curr.nseg;
    }
}
/**
 * @param {$T.monst | null} worm struct monst *
 * @returns {Promise<void>}
 */
export async function redraw_worm(worm) {   // worm.c:990
    let curr = null;
    curr = wtails[worm.wormno];
    while (curr) {
        await newsym(curr.wx, curr.wy);
        curr = curr.nseg;
    }
}
async function newseg() {
    return $c.asRec(await alloc(16), $T.wseg, 16);
}
function dealloc_seg(wseg) {
    $c.free(wseg);
}

export function $init() {
    wheads.fill(null);
    $c.init(wheads, [
        null
    ]);
    wtails.fill(null);
    $c.init(wtails, [
        null
    ]);
    wgrowtime.fill(0);
    $c.init(wgrowtime, [
        0
    ]);
}
